import{_ as e,o as i,c as l,ae as t}from"./chunks/framework.RRduUuAx.js";const _=JSON.parse('{"title":"定时记账说明","description":"","frontmatter":{},"headers":[],"relativePath":"v1/zh/guide/12-scheduled-accounting-guide.md","filePath":"v1/zh/guide/12-scheduled-accounting-guide.md"}'),r={name:"v1/zh/guide/12-scheduled-accounting-guide.md"};function o(h,a,d,n,u,c){return i(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="定时记账说明" tabindex="-1">定时记账说明 <a class="header-anchor" href="#定时记账说明" aria-label="Permalink to &quot;定时记账说明&quot;">​</a></h1><h2 id="_1-这是什么功能" tabindex="-1">1. 这是什么功能 <a class="header-anchor" href="#_1-这是什么功能" aria-label="Permalink to &quot;1. 这是什么功能&quot;">​</a></h2><p>“定时记账”用于把一些固定、重复发生的收支（例如房租、水电、会员订阅、工资等）设置成规则，让系统按规则自动生成账单，减少重复手动录入。</p><h2 id="_2-适用场景" tabindex="-1">2. 适用场景 <a class="header-anchor" href="#_2-适用场景" aria-label="Permalink to &quot;2. 适用场景&quot;">​</a></h2><ul><li>每月房租、房贷、信用卡还款</li><li>每周通勤交通费、固定餐补</li><li>每月订阅服务（视频会员、网盘等）</li><li>每月固定收入（工资、补贴等）</li></ul><h2 id="_3-如何使用" tabindex="-1">3. 如何使用 <a class="header-anchor" href="#_3-如何使用" aria-label="Permalink to &quot;3. 如何使用&quot;">​</a></h2><ol><li>进入“设置”页面，找到“定时记账”</li><li>新建一条定时规则，填写： <ul><li>收支类型：支出 / 收入</li><li>分类（收支项）</li><li>金额</li><li>账户</li><li>标签、备注（可选）</li><li>执行周期：每天 / 每周 / 每月（按规则选择具体日期或星期）</li><li>起止时间：开始时间必填，结束时间可选（用于到期自动停止）</li></ul></li><li>保存后，规则会出现在定时记账列表中</li><li>到达触发时间后，系统会按规则生成账单</li></ol><h2 id="_4-使用规则与注意事项" tabindex="-1">4. 使用规则与注意事项 <a class="header-anchor" href="#_4-使用规则与注意事项" aria-label="Permalink to &quot;4. 使用规则与注意事项&quot;">​</a></h2><ul><li>定时记账生成的账单与普通手动账单一致：会参与列表展示与统计汇总。</li><li>如果您长期不打开 App，部分设备可能无法做到“严格准点”生成；下次打开 App 时，系统会补齐到期但尚未生成的账单（避免漏记）。</li><li>建议定期检查规则列表，确认金额、分类、账户仍符合当前实际情况（例如房租涨价、换卡等）。</li><li>暂停/终止规则后将不再继续生成账单；恢复启用后会从下一次周期继续执行。</li></ul><h2 id="_5-常见问题" tabindex="-1">5. 常见问题 <a class="header-anchor" href="#_5-常见问题" aria-label="Permalink to &quot;5. 常见问题&quot;">​</a></h2><h3 id="q1-定时记账生成错了怎么办" tabindex="-1">Q1：定时记账生成错了怎么办？ <a class="header-anchor" href="#q1-定时记账生成错了怎么办" aria-label="Permalink to &quot;Q1：定时记账生成错了怎么办？&quot;">​</a></h3><p>定时记账生成的账单可以像普通账单一样编辑或删除。若经常出错，建议直接调整对应的定时规则（金额/周期/账户等）。</p><h3 id="q2-规则改了-之前生成的账单会自动跟着变吗" tabindex="-1">Q2：规则改了，之前生成的账单会自动跟着变吗？ <a class="header-anchor" href="#q2-规则改了-之前生成的账单会自动跟着变吗" aria-label="Permalink to &quot;Q2：规则改了，之前生成的账单会自动跟着变吗？&quot;">​</a></h3><p>不会。规则修改只影响后续生成的账单；历史账单保持不变，便于追溯。</p><h3 id="q3-同一天会生成多笔吗" tabindex="-1">Q3：同一天会生成多笔吗？ <a class="header-anchor" href="#q3-同一天会生成多笔吗" aria-label="Permalink to &quot;Q3：同一天会生成多笔吗？&quot;">​</a></h3><p>如果您设置了多条规则，系统会分别生成对应的账单。对于同一条规则，系统会尽量避免重复生成。</p>',16)])])}const q=e(r,[["render",o]]);export{_ as __pageData,q as default};
